def has_duplicate_quadratic(xs):        # O(n^2) time, O(1) space
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            if xs[i] == xs[j]:
                return True
    return False

def has_duplicate_linear(xs):           # O(n) time, O(n) space
    seen = set()
    for x in xs:
        if x in seen:
            return True
        seen.add(x)
    return False

class Node:
    def __init__(self, value, next=None):
        self.value, self.next = value, next

def reverse(head):
    prev = None
    while head:
        nxt = head.next      # remember the rest
        head.next = prev     # flip this link
        prev, head = head, nxt
    return prev

